  #define PI 3.14159265359

        const float numParticles = 9.;
        const float glowMultiplier =5.;

        precision highp float;

vec4 main1(in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;


    float time;
    if (iMouse.z>0.) {
    time= iMouse.x/100.;
    } else {
    time = (iTime) * 1.554;
    }
    vec3 color = vec3(0.0);
    float intensity = 0.0;

    int NUM_PARTICLES = int(numParticles);

    float dynamicScale = 3.14 + sin(time * 0.21) * 0.8;

    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (sin(time) + 1.0) / 2.0 * id / 30.0;

        float theta = fract(id + particleTime * 0.09) * 20.0 * dynamicScale;
        float phi = fract(id * 1.618 + particleTime * 0.015) * 2.0*dynamicScale;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * -sin(theta),
            cos(phi)
        );

        float angle = time * 0.468;
        mat3 rotation = mat3(
            cos(angle), 0.0, -sin(angle),
            0.0,        1.0,  0.0,
            sin(angle), 0.0,  cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 1.4+(sin(time)+1.0)/2.0/2.0);

        float dist = length(uv - screenPos);
        float glow = exp(-dist * glowMultiplier);

        intensity += glow * (0.9 + abs(sin(iTime / 100.0)));
        color += glow * vec3(
            0.4 + 0.6 * sin(id * PI * 2.0),
            0.3 + 0.4 * sin(time * 2.0),
            1.0
        );
    }


if (intensity < 0.55) {

               intensity = clamp(intensity,0.001,1.0);

return vec4(.650/exp(intensity/.41));
} else
    if (intensity < .70) {
    intensity = clamp(intensity,0.0,1.5);
    return vec4(.9-color.gbr*vec3(exp(intensity*.910)),1.0);
    }else
    if (intensity < 1.90) {
    intensity = clamp(intensity,0.3,1.4);
    return vec4(1.4-color.bgr*vec3(exp(intensity*.910)),1.0);
    }else
    if (intensity < 3.90) {
    intensity = clamp(intensity,0.0,.1);
    return vec4(1.4-color.bbr*vec3(exp(intensity*.910)),1.0);
    } else {
        intensity = clamp(intensity,0.3,1.0);
    return vec4(.50-color.brb/.3 * intensity, 1.0);
    }

}


