{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
    fragColor = main1(fragCoord);
}

vec2 mainSound(int samp, float time)
    {
    time*=1.554/1.0;

    float measure=48.0;
    float localTime=mod(time,measure*2.);
    int chordIndex=int(floor(localTime/4.0))%4;
    float cChords[12]=float[12](
        261.63,329.63,392.0,
        220.0,261.63,329.63,
        174.61,220.0,261.63,
        196.0,246.94,392.0
    );
    float chord=0.0;
    for(int i=0;i<3;i++){
        chord+=sin(6.2831/1.*cChords[chordIndex*3 + i]*time)*0.12;
    }
    float melody[16]=float[16](
        261.63,293.66,329.63,349.23,
        392.0,349.23,329.63,293.66,
        261.63,293.66,329.63,392.0,
        440.0,392.0,349.23,329.63
    );
    int noteIndex=0;
       float pad = (sin(time)*.50+.5)*.3+sin(6.2831*time)*1.4;
       float env=exp(-1.0*(localTime-floor(localTime)));
      if(time>6.0){
       env=exp(-4.0*(localTime-floor(localTime)));
         pad=sin(6.2831*0.07*time)*0.3+sin(6.2831*0.1*time)*0.9;
         noteIndex=int(floor(localTime))%16;
     }

    float mainTone=sin(6.2831*melody[noteIndex]*time)*env*0.15;

    float rnd=fract(sin(float(samp)*12.9898+time*78.233)*43758.5453);
    float noise=(rnd-0.2)*0.01;
    float drum=0.0;
    if(time>16.0){
        float dPhase=fract(time*0.5);
        float dEnv=exp(-20.0*dPhase);
        float baseKick=sin(6.2831*60.0*time)*dEnv;
        float echo1=sin(6.2831*60.0*(time-0.3))*exp(-30.0*fract((time-0.6)*0.5))*0.4;
        float echo2=sin(6.2831*20.0*(time-0.6))*exp(-30.0*fract((time-0.9)*0.5))*0.2;
        drum=baseKick+echo1+echo2;
    }

    float mix=chord+mainTone+pad+noise+drum*0.21215;
    float pan=0.5+0.4*sin(6.2831*0.02*time);
    float left=mix*(1.0-pan);
    float right=mix*pan;
    return vec2(left,right);
}
